                    <div class="faq-question">Can I arrive late?</div>
                    <div class="faq-answer">Yes, entry is permitted until 23:00. However, some experiences like the Hidden Collection Tour and Artist Talks may have limited capacity after their start time.</div>
                </div>
                <div class="faq-item">
                    <div class="faq-question">Are photos allowed?</div>
                    <div class="faq-answer">Yes, non-flash photography is permitted in all public areas. Flash photography and tripods are prohibited to preserve the atmosphere and protect the artworks.</div>
                </div>
                <div class="faq-item">
                    <div class="faq-question">Is the venue accessible?</div>
                    <div class="faq-answer">Yes, the entire venue is fully wheelchair accessible with elevators to all floors. Wheelchair rentals are available at the entrance, and sign language interpreters can be arranged with 48 hours' notice.</div>
                </div>
                <div class="faq-item">
                    <div class="faq-question">Can I change my ticket tier?</div>
                    <div class="faq-answer">Yes, you can upgrade your ticket up to 24 hours before the event. Downgrades are not permitted. Contact us at info@artifactmuseumnight.com for assistance.</div>
                </div>
                <div class="faq-item">
                    <div class="faq-question">How do I save the event to my calendar?</div>
                    <div class="faq-answer">Click the "Save to Calendar" button in the hero section. A .ics file will download automatically. Open it with your calendar app (Google Calendar, Apple Calendar, Outlook, etc.) to add the event.</div>
                </div>
            </div>
        </div>
    </section>

    <!-- Newsletter -->
    <section class="newsletter">
        <div class="container">
            <h2>Stay Updated</h2>
            <p>Sign up for exclusive updates about ARTIFACT: Museum Night.</p>
            <form class="newsletter-form" id="newsletter-form">
                <input type="email" class="newsletter-input" id="newsletter-email" placeholder="Your email address" required>
                <button type="submit" class="newsletter-button">Subscribe</button>
            </form>
            <div class="newsletter-error" id="newsletter-error">Please enter a valid email address.</div>
        </div>
    </section>

    <!-- Footer -->
    <footer class="footer">
        <div class="container">
            <div class="footer-logo">ARTIFACT</div>
            <p class="footer-credits">A cinematic after-hours museum experience</p>
            <div class="footer-links">
                <a href="#">Privacy Policy</a>
                <a href="#">Terms of Service</a>
                <a href="#">Contact</a>
                <a href="#">Media</a>
            </div>
            <p class="footer-note">Demo landing page — no real ticket purchase.</p>
        </div>
    </footer>

    <script>
        // Smooth scroll for nav links
        document.querySelectorAll('.nav-links a').forEach(anchor => {
            anchor.addEventListener('click', function(e) {
                e.preventDefault();
                const targetId = this.getAttribute('href');
                const targetElement = document.querySelector(targetId);
                if (targetElement) {
                    window.scrollTo({
                        top: targetElement.offsetTop - 80,
                        behavior: 'smooth'
                    });
                }
            });
        });

        // Sticky navbar
        window.addEventListener('scroll', () => {
            const navbar = document.querySelector('.navbar');
            if (window.scrollY > 50) {
                navbar.classList.add('scrolled');
            } else {
                navbar.classList.remove('scrolled');
            }
        });

        // Mobile menu toggle
        const menuToggle = document.querySelector('.menu-toggle');
        const navLinks = document.querySelector('.nav-links');
        menuToggle.addEventListener('click', () => {
            navLinks.classList.toggle('active');
        });

        // Active nav state on scroll
        const sections = document.querySelectorAll('section');
        const navLinksItems = document.querySelectorAll('.nav-links a');

        window.addEventListener('scroll', () => {
            let current = '';

            sections.forEach(section => {
                const sectionTop = section.offsetTop;
                const sectionHeight = section.clientHeight;
                if (window.scrollY >= sectionTop - 100) {
                    current = section.getAttribute('id');
                }
            });

            navLinksItems.forEach(link => {
                link.classList.remove('active');
                if (link.getAttribute('href') === '#' + current) {
                    link.classList.add('active');
                }
            });
        });

        // Artist modals
        const artistCards = document.querySelectorAll('.artist-card');
        const modals = document.querySelectorAll('.modal');
        const modalCloseButtons = document.querySelectorAll('.modal-close');
        const viewDetailsButtons = document.querySelectorAll('.view-details');

        artistCards.forEach(card => {
            card.addEventListener('click', () => {
                const modalId = card.getAttribute('data-modal');
                const modal = document.getElementById(modalId);
                modal.style.display = 'flex';
            });
        });

        modalCloseButtons.forEach(button => {
            button.addEventListener('click', () => {
                const modal = button.closest('.modal');
                modal.style.display = 'none';
            });
        });

        viewDetailsButtons.forEach(button => {
            button.addEventListener('click', () => {
                const modal = button.closest('.modal');
                modal.style.display = 'none';
            });
        });

        // Close modal on ESC
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') {
                modals.forEach(modal => {
                    modal.style.display = 'none';
                });
            }
        });

        // Close modal on backdrop click
        modals.forEach(modal => {
            modal.addEventListener('click', (e) => {
                if (e.target === modal) {
                    modal.style.display = 'none';
                }
            });
        });

        // Ticket tier selection
        const ticketButtons = document.querySelectorAll('.ticket-button');
        const ticketModal = document.getElementById('ticket-modal');
        const selectedTierDisplay = document.getElementById('selected-tier');
        const ticketForm = document.getElementById('ticket-form');
        const confirmTicketButton = document.getElementById('confirm-ticket');

        ticketButtons.forEach(button => {
            button.addEventListener('click', () => {
                const card = button.closest('.ticket-card');
                const tierName = card.querySelector('.ticket-name').textContent;
                selectedTierDisplay.innerHTML = `Selected Tier: <strong>${tierName}</strong>`;
                ticketModal.style.display = 'flex';
            });
        });

        // Form validation
        const emailInputs = document.querySelectorAll('input[type="email"]');
        const emailErrors = document.querySelectorAll('.newsletter-error');

        emailInputs.forEach((input, index) => {
            input.addEventListener('blur', () => {
                const email = input.value;
                const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                const error = emailErrors[index];
                if (email && !emailRegex.test(email)) {
                    error.style.display = 'block';
                } else {
                    error.style.display = 'none';
                }
            });
        });

        // Newsletter form submission
        document.getElementById('newsletter-form').addEventListener('submit', (e) => {
            e.preventDefault();
            const emailInput = document.getElementById('newsletter-email');
            const emailError = document.getElementById('newsletter-error');
            const email = emailInput.value;
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

            if (emailRegex.test(email)) {
                emailError.style.display = 'none';
                showToast('Thank you for subscribing!');
                emailInput.value = '';
            } else {
                emailError.style.display = 'block';
            }
        });

        // Ticket form submission
        ticketForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const name = document.getElementById('name').value;
            const email = document.getElementById('email').value;
            const tickets = document.getElementById('tickets').value;
            const terms = document.getElementById('terms').checked;
            const emailError = document.getElementById('email-error');
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

            if (!name || !email || !terms || !emailRegex.test(email)) {
                if (!emailRegex.test(email)) {
                    emailError.style.display = 'block';
                }
                return;
            }

            emailError.style.display = 'none';
            showToast(`Reservation confirmed for ${tickets} ticket(s) under ${name}!`);
            ticketForm.reset();
            document.getElementById('terms').checked = false;
            ticketModal.style.display = 'none';
        });

        // Save to Calendar
        document.getElementById('save-calendar').addEventListener('click', () => {
            const icsContent = `BEGIN:VCALENDAR
VERSION:2.0
PRODID:-//ARTIFACT//EN
CALSCALE:GREGORIAN
BEGIN:VEVENT
UID:artifact-museum-night-2026
DTSTAMP:20261018T120000Z
DTSTART:20261018T190000Z
DTEND:20261019T020000Z
SUMMARY:ARTIFACT: Museum Night
DESCRIPTION:A cinematic after-hours museum event with exhibitions, performances, talks, and guided tours.
LOCATION:The Old Gallery, Warsaw
END:VEVENT
END:VCALENDAR`;

            const blob = new Blob([icsContent], { type: 'text/calendar' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = 'artifact-museum-night.ics';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
            showToast('Calendar file downloaded!');
        });

        // Toast notification
        function showToast(message) {
            const toast = document.createElement('div');
            toast.className = 'toast';
            toast.textContent = message;
            document.body.appendChild(toast);
            setTimeout(() => {
                toast.classList.add('show');
            }, 100);
            setTimeout(() => {
                toast.classList.remove('show');
                setTimeout(() => {
                    document.body.removeChild(toast);
                }, 400);
            }, 3000);
        }

        // FAQ accordion
        const faqItems = document.querySelectorAll('.faq-item');

        faqItems.forEach(item => {
            const question = item.querySelector('.faq-question');
            question.addEventListener('click', () => {
                item.classList.toggle('active');
            });
        });

        // Scroll reveal animations
        const revealElements = document.querySelectorAll('.hero-content, .feature-card, .timeline-item, .artist-card, .ticket-card, .faq-item');

        const observerOptions = {
            threshold: 0.1
        };

        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.style.opacity = 1;
                    entry.target.style.transform = 'translateY(0)';
                }
            });
        }, observerOptions);

        revealElements.forEach(element => {
            element.style.opacity = 0;
            element.style.transform = 'translateY(30px)';
            element.style.transition = 'opacity 0.6s ease, transform 0.6s ease';
            observer.observe(element);
        });

        // Set initial opacity for elements
        document.querySelectorAll('.hero-content, .feature-card, .timeline-item, .artist-card, .ticket-card, .faq-item').forEach(el => {
            el.style.opacity = 0;
            el.style.transform = 'translateY(30px)';
            el.style.transition = 'opacity 0.6s ease, transform 0.6s ease';
        });

        // Intersection Observer for scroll reveal
        const revealObserver = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('reveal');
                    entry.target.style.opacity = 1;
                    entry.target.style.transform = 'translateY(0)';
                }
            });
        }, { threshold: 0.1 });

        document.querySelectorAll('.hero-content, .feature-card, .timeline-item, .artist-card, .ticket-card, .faq-item').forEach(el => {
            revealObserver.observe(el);
        });

        // Add reveal class for CSS
        const style = document.createElement('style');
        style.textContent = `
            .reveal {
                opacity: 1 !important;
                transform: translateY(0) !important;
            }
        `;
        document.head.appendChild(style);
    </script>
</body>
</html>
"}
